#!/bin/bash
# Staged by Claude 2026-10-01 (v2) — fixes the empty-password failure.
# ssh reads passwords from /dev/tty, not stdin, so the prompt went to the
# VM's invisible screen and the read landed nowhere: two "Failed password"
# in one second at 03:53:58 with nothing typed. SSH_ASKPASS now handles it.
# Run as hamsci in the decoder VM:  bash ~/hf-deploy-console-bridge.sh
# Undo: sudo rm -rf /etc/systemd/system/getty@tty1.service.d && sudo systemctl daemon-reload && sudo systemctl restart getty@tty1
set -eu



echo "$BR" | base64 -d > /tmp/_br; echo "$AP" | base64 -d > /tmp/_ap; echo "$CF" | base64 -d > /tmp/_cf
[ "$(wc -c < /tmp/_br)" = 2959 ] || { echo "FATAL: bridge wrong size"; exit 1; }
[ "$(wc -c < /tmp/_ap)" = 1331 ] || { echo "FATAL: askpass wrong size"; exit 1; }
[ "$(wc -c < /tmp/_cf)" = 406 ] || { echo "FATAL: conf wrong size"; exit 1; }
bash -n /tmp/_br && bash -n /tmp/_ap || { echo "FATAL: does not parse"; exit 1; }
sudo install -m 755 /tmp/_br /usr/local/sbin/sigmond-console-bridge
sudo install -m 755 /tmp/_ap /usr/local/sbin/sigmond-console-askpass
sudo mkdir -p /etc/systemd/system/getty@tty1.service.d
sudo install -m 644 /tmp/_cf /etc/systemd/system/getty@tty1.service.d/sigmond-console-bridge.conf
sudo systemctl daemon-reload
sudo systemctl restart getty@tty1.service
sleep 3
echo "getty@tty1: $(systemctl is-active getty@tty1)"
echo "DONE — look at the monitor; it should now TELL you to type the password."
